// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    Recorder rec;

    function setUp() public {
        c = new SimpleWallet();
        rec = new Recorder();
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, address(c).balance == 0 ? 0 : type(uint128).max);
        vm.deal(address(c), 10 ether);
        uint256 before = address(c).balance;

        vm.prank(c.owner());
        c.sendMoney(address(rec), amount);

        uint256 drop = before - address(c).balance;
        assertTrue(rec.lastValue() == amount && drop == amount,
            "sendMoney must transfer exactly _value wei out of the contract");
    }
}

contract Recorder {
    uint256 public lastValue;

    fallback() external payable {
        lastValue = msg.value;
    }

    receive() external payable {
        lastValue = msg.value;
    }
}
